#include <bits/stdc++.h>
using namespace std;

class Component;

class Mediator {
public:
    virtual void notify(Component& sender, const string& event) = 0;
    virtual ~Mediator() = default;
};

class Component {
    Mediator& mediator;
public:
    Component(Mediator& mediator) : mediator(mediator) {}

    void change() {
        // Everyone only talks to the mediator
        mediator.notify(*this, "changed");
    }
};

class SimpleMediator : public Mediator {
public:
    void notify(Component& sender, const string& event) override {
        cout << "Component triggered event: " << event << endl;
    }
};

int main() {
    SimpleMediator mediator;
    Component component(mediator);
    component.change();
    return 0;
}

